package com.metabuild.modules.admin.company.persistence;
import com.metabuild.modules.admin.company.application.*;import com.metabuild.shared.kernel.*;import java.time.LocalDate;import java.util.UUID;import org.jooq.*;import org.jooq.exception.IntegrityConstraintViolationException;import org.springframework.dao.DuplicateKeyException;
public final class JooqCompanyRepository implements CompanyRepository {private final DSLContext db;private final UuidV7Generator ids;public JooqCompanyRepository(DSLContext db,UuidV7Generator ids){this.db=db;this.ids=ids;}private static CompanyView row(org.jooq.Record r){return new CompanyView(r.get("id",UUID.class),r.get("name",String.class),Boolean.TRUE.equals(r.get("verified",Boolean.class)),r.get("domain",String.class),r.get("code",String.class),r.get("industry",String.class),r.get("scale",String.class),r.get("data_residency",String.class),r.get("created_date",LocalDate.class).toString(),r.get("contact_name",String.class),r.get("contact_email",String.class),r.get("contact_phone",String.class),r.get("landline",String.class),r.get("address",String.class),r.get("postal_code",String.class));}public CompanyView get(){return db.fetchOptional("select * from mb_company where singleton_key=1").map(JooqCompanyRepository::row).orElseThrow(()->new NotFound(()->"company.not-found","Company not found"));}public CompanyView update(UUID actor,CompanyUpdate x){UUID companyId=get().id();try{return db.transactionResult(configuration->{DSLContext tx=org.jooq.impl.DSL.using(configuration);tx.execute("update mb_company set name=?,verified=?,domain=?,code=?,industry=?,scale=?,data_residency=?,created_date=?::date,contact_name=?,contact_email=?,contact_phone=?,landline=?,address=?,postal_code=?,updated_at=current_timestamp where id=?",x.name().trim(),x.verified(),x.domain().trim(),x.code().trim(),x.industry().trim(),x.scale().trim(),x.dataResidency().trim(),x.createdAt(),x.contactName().trim(),x.contactEmail().trim(),x.contactPhone().trim(),x.landline()==null?"":x.landline().trim(),x.address().trim(),x.postalCode().trim(),companyId);tx.execute("insert into mb_operation_log(id,actor_id,operation,resource_type,resource_id,success,detail) values(?,?,'company.update','company',?,true,'{}'::jsonb)",ids.generate(),actor,companyId);return tx.fetchOptional("select * from mb_company where id=?",companyId).map(JooqCompanyRepository::row).orElseThrow();});}catch(IntegrityConstraintViolationException | DuplicateKeyException e){throw new Conflict(()->"company.code.conflict","Company code already exists");}}}
